   [dependencies]
   image = "0.24.0"
   ```

2. **Required imports:**
   ```rust
   use image::codecs::jpeg::JpegEncoder;
   use image::io::Reader as ImageReader;
   use image::{DynamicImage, ImageEncoder};
   use std::fs::File;
   use std::path::Path;
   ```

3. **Read the source image file:**
   ```rust
   let orig_file = File::open(orig_path).map_err(|_| create_err())?;
   let file_reader = BufReader::new(orig_file);
   let image: DynamicImage = ImageReader::new(file_reader)
       .with_guessed_format()
       .map_err(|_| create_err())?
       .decode()
       .map_err(|_| create_err())?;
   ```

4. **Create destination path and file:**
   ```rust
   let dest_path = Path::new("your/custom/path").join("filename.jpg");
   let mut file_writer = File::create(dest_path).map_err(|_| create_err())?;
   ```

5. **Encode with specific quality level (e.g., 75%):**
   ```rust
   let encoder = JpegEncoder::new_with_quality(&mut file_writer, 75);
   encoder
       .write_image(
           image.as_bytes(),
           image.width(),
           image.height(),
           image.color(),
       )
       .map_err(|_| create_err())?;
   ```

### Async Version (with Tokio):

For better performance in web apps, wrap the synchronous JPEG encoding in `tokio::task::spawn_blocking`:

```rust
use std::io::Cursor;

let write_result: Result<Vec<u8>, ImageError> = tokio::task::spawn_blocking(move || {
    let mut write_buffer: Vec<u8> = vec![];
    let mut write_cursor = Cursor::new(&mut write_buffer);
    let _ = JpegEncoder::new_with_quality(&mut write_cursor, 75).write_image(
        image.as_bytes(),
        image.width(),
        image.height(),
        image.color(),
    )?;
    Ok(write_buffer)
}).await.map_err(|_| create_err())?;

let write_bytes = write_result.map_err(|_| create_err())?;
let dest_path = Path::new("your/custom/path").join("filename.jpg");
tokio::fs::write(dest_path, &write_bytes).await.map_err(|_| create_err())?;
```

