```rust
use actix_web::HttpRequest;
use base64::{Engine, engine::general_purpose};

#[derive(Debug)]
pub struct Credentials {
    pub username: String,
    pub password: String,
}

pub async fn extract_credentials(req: HttpRequest) -> Result<Credentials, Error> {
    let header_value = req.headers().get("Authorization")
        .ok_or_return("No credentials provided");

    let encoded = header_value.to_str().ok_or_return("Invalid credentials");

    if !encoded.starts_with("Basic ") {
        return Err("Invalid credentials");
    }

    let base64_credentials = &encoded[6..];
    let decoded = general_purpose::STANDARD.decode(base64_credentials)?;
    let credentials = String::from_utf8(decoded)?;

    let parts: Vec<&str> = credentials.splitn(2, ':').collect();
    if parts.len() == 2 {
        Ok(Credentials {
            username: parts[0].to_string(),
            password: parts[1].to_string(),
        })
    } else {
        Err("Invalid credentials")
    }
}
```

**3. Create the login endpoint** (`src/api/auth/login.rs`):
```rust
use actix_web::HttpResponse;

pub async fn login(req: actix_web::HttpRequest) -> HttpResponse {
    let credentials = extract_credentials(req).await?;

    // Look up user and verify password
    let user = db.get_user_by_username(credentials.username).await?;
    if user.password == credentials.password {
        // Return a token or success response
        HttpResponse::Ok().json(/* token */)
    } else {
        HttpResponse::Unauthorized().finish()
    }
}
```

**4. Mount to a dedicated auth scope** (`src/api/auth/mod.rs`):
```rust
use actix_web::web::{ServiceConfig, get, scope};

pub fn auth_factory(app: &mut ServiceConfig) {
    app.service(
        scope("/api/v1/auth")
            .route("/login", get().to(login::login))
    );
}
```

## Approach 2: Rocket with Form Data (POST)

**1. Define the login form struct** (`src/models/user.rs`):
```rust
#[derive(FromForm)]
pub struct Login<'r> {
    pub username: &'r str,
    pub password: &'r str,
}
```

**2. Create a login route** (`src/routes/api.rs`):
```rust
