pub async fn login(
    db: Connection<DBConnection>,
    login: Login,
) -> Result<Json<Token>, Json<OurError>> {
    let user = User::find_by_login(db, login).await?;
    Ok(Json(Token::generate(user.id)))
}
```

**3. Mount to a dedicated routes group** (`src/main.rs`):
```rust
