use std::fs::OpenOptions;
use std::path::Path;

// Create options, set append mode, and open the file
let path = Path::new("myfile.txt");
let file = OpenOptions::new()
    .append(true)   // Enable append mode
    .create(true)   // Optional: Create file if it doesn't exist
    .open(path)?;
```

### Key Points
1.  **`append(true)`**: This method sets the file opening mode to append. When the file is opened, the write cursor is positioned at the end of the file. Any subsequent writes will add data after the existing content.
2.  **`OpenOptions::new()`**: Initializes the options builder. By default, files are opened in read-only mode.
3.  **`.open(path)`**: This final method executes the file open operation using the configured options, returning a `std::io::Result<File>`.
4.  **`create(true)`**: Often used alongside `append(true)` to ensure the file is created if it does not already exist, preventing an error on the first write to a new file.

### Example: Appending to a Log File
```rust
use std::fs::OpenOptions;
use std::io::Write;
use std::path::Path;

fn append_to_log(file_path: &Path, message: &str) -> std::io::Result<()> {
    let mut file = OpenOptions::new()
        .append(true)
        .create(true)
        .open(file_path)?;

    // Write the message followed by a newline
    file.write_all(format!("{}\n", message).as_bytes())?;
    Ok(())
}
```

